"""nfare.py -- regular expressions without catastrophic backtracking.

Pipeline:
  1. Parse the pattern (recursive descent) and simultaneously build an NFA
     using Thompson's construction: every operator is implemented with a
     fixed-size gadget of epsilon transitions, so an m-character pattern
     yields an NFA with O(m) states and O(m) transitions.
  2. Simulate the NFA on the input by tracking the *set* of states the
     machine could currently be in (epsilon-closure + one hop per input
     character). Each input character costs O(states + transitions), so a
     string of length n is matched in O(n * m) time -- always. There is no
     backtracking whatsoever, hence no exponential blowup.

Supported syntax:
  literals      a b c ...
  .             any character except newline (like Python's re by default)
  *             zero or more of the preceding atom
  +             one or more of the preceding atom
  ?             zero or one of the preceding atom
  |             alternation
  (...)         grouping
  {n} {n,} {n,m}
                bounded repetition, expanded structurally at compile time

Public API:
  fullmatch(pattern, string) -> bool
"""

from __future__ import annotations


class ParseError(ValueError):
    """Raised when the pattern violates the supported grammar."""


# ---------------------------------------------------------------------------
# NFA representation
# ---------------------------------------------------------------------------

EPSILON = None          # epsilon-transition marker
ANY = object()          # '.' wildcard marker (matches anything except '\n')


class NFA:
    """A Thompson-style NFA.

    ``trans[s]`` is the outgoing transition list of state ``s``:
    a list of ``(label, dst)`` pairs where ``label`` is EPSILON, ANY,
    or a concrete 1-character string.
    """

    __slots__ = ("trans", "start", "accept")

    def __init__(self):
        self.trans: list[list[tuple]] = []
        self.start: int | None = None
        self.accept: int | None = None

    def new_state(self) -> int:
        self.trans.append([])
        return len(self.trans) - 1

    def add(self, src: int, label, dst: int) -> None:
        self.trans[src].append((label, dst))

    @property
    def num_states(self) -> int:
        return len(self.trans)


# ---------------------------------------------------------------------------
# Parser / Thompson construction
#
# A "fragment" is a partially built sub-automaton represented as the pair
# (start, accept). Fragments are composed purely with epsilon edges, which
# keeps every gadget constant-sized (the classic Thompson construction).
# ---------------------------------------------------------------------------

MAX_REPEAT = 1000  # sanity cap for {n,m} expansion


class _Parser:
    def __init__(self, pattern: str):
        self.pat = pattern
        self.i = 0
        self.nfa = NFA()

    # --- token helpers -----------------------------------------------------
    def peek(self):
        return self.pat[self.i] if self.i < len(self.pat) else None

    def expect(self, ch: str) -> None:
        if self.peek() != ch:
            raise ParseError(
                f"expected {ch!r} at position {self.i} in {self.pat!r}"
            )
        self.i += 1

    # --- grammar -----------------------------------------------------------
    def parse(self):
        frag = self._alternation()
        if self.i != len(self.pat):
            # Only way to stop early at top level is an unmatched ')'.
            raise ParseError(f"unbalanced parenthesis at position {self.i}")
        self.nfa.start, self.nfa.accept = frag
        return self.nfa

    def _alternation(self):
        frags = [self._concat()]
        while self.peek() == "|":
            self.i += 1
            frags.append(self._concat())
        if len(frags) == 1:
            return frags[0]
        start = self.nfa.new_state()
        accept = self.nfa.new_state()
        for s, a in frags:
            self.nfa.add(start, EPSILON, s)
            self.nfa.add(a, EPSILON, accept)
        return (start, accept)

    def _concat(self):
        frags = []
        while self.peek() is not None and self.peek() not in "|)":
            frags.append(self._repeat())
        if not frags:
            # Empty expression: pure epsilon fragment.
            s = self.nfa.new_state()
            return (s, s)
        for (_, a1), (s2, _) in zip(frags, frags[1:]):
            self.nfa.add(a1, EPSILON, s2)
        return (frags[0][0], frags[-1][1])

    def _repeat(self):
        """atom followed by an optional single quantifier."""
        atom_start = self.i
        frag = self._atom()

        c = self.peek()
        if c == "*":
            self.i += 1
            return self._finish_repeat(frag, self._star(frag))
        if c == "+":
            self.i += 1
            return self._finish_repeat(frag, self._plus(frag))
        if c == "?":
            self.i += 1
            return self._finish_repeat(frag, self._opt(frag))
        if c == "{":
            return self._counted_repeat(atom_start, frag)
        return frag

    def _finish_repeat(self, atom_frag, rep_frag):
        # Reject stacked quantifiers like a** (Python's re rejects them too).
        nxt = self.peek()
        if nxt in ("*", "+", "?") or (nxt == "{" and self._looks_like_count()):
            raise ParseError(f"multiple repeat at position {self.i}")
        return rep_frag

    def _looks_like_count(self) -> bool:
        j = self.i + 1
        saw_digit = False
        while j < len(self.pat) and self.pat[j].isdigit():
            saw_digit = True
            j += 1
        if j < len(self.pat) and self.pat[j] == ",":
            j += 1
            while j < len(self.pat) and self.pat[j].isdigit():
                j += 1
        return saw_digit and j < len(self.pat) and self.pat[j] == "}"

    def _counted_repeat(self, atom_start: int, first_frag):
        """Handle {n}, {n,}, {n,m} by structural expansion."""
        self.expect("{")
        lo_digits = self._digits()
        if lo_digits is None:
            raise ParseError(f"bad repeat specifier at position {self.i}")
        lo = int(lo_digits)
        hi = lo
        if self.peek() == ",":
            self.i += 1
            hi_digits = self._digits()
            hi = int(hi_digits) if hi_digits is not None else None  # {n,}
        self.expect("}")

        if hi is not None and hi < lo:
            raise ParseError(
                f"min repeat greater than max repeat at position {self.i}"
            )
        if lo > MAX_REPEAT or (hi is not None and hi > MAX_REPEAT):
            raise ParseError("repeat count too large")

        pieces = [first_frag]  # first copy was already parsed
        total = hi if hi is not None else lo + 1
        for k in range(1, total):
            # Re-parse the same atom for each additional copy: sharing one
            # sub-NFA between several predecessors would violate the NFA
            # semantics (it would act like a DAG-compressed automaton).
            self.i = atom_start
            extra = self._atom()
            if hi is not None and k >= lo:
                extra = self._opt(extra)   # the optional part of {n,m}
            elif hi is None and k >= lo:
                break                       # shouldn't happen (lo+1 guard)
            pieces.append(extra)
        if hi is None:
            # {n,}: n mandatory copies followed by a starred copy.
            self.i = atom_start
            tail = self._star(self._atom())
            pieces.append(tail)

        if len(pieces) == 1:
            return pieces[0]
        for (_, a1), (s2, _) in zip(pieces, pieces[1:]):
            self.nfa.add(a1, EPSILON, s2)
        return (pieces[0][0], pieces[-1][1])

    def _digits(self):
        j = self.i
        while j < len(self.pat) and self.pat[j].isdigit():
            j += 1
        if j == self.i:
            return None
        d = self.pat[self.i:j]
        self.i = j
        return d

    # --- quantifier gadgets (constant size each) ---------------------------
    def _star(self, frag):
        s, a = frag
        split = self.nfa.new_state()
        accept = self.nfa.new_state()
        self.nfa.add(split, EPSILON, s)       # enter the body
        self.nfa.add(split, EPSILON, accept)  # ...or skip it entirely
        self.nfa.add(a, EPSILON, split)       # loop back
        return (split, accept)

    def _plus(self, frag):
        s, a = frag
        split = self.nfa.new_state()
        accept = self.nfa.new_state()
        self.nfa.add(a, EPSILON, split)       # after one pass...
        self.nfa.add(split, EPSILON, s)       # ...loop back, or
        self.nfa.add(split, EPSILON, accept)  # ...stop
        return (s, accept)

    def _opt(self, frag):
        s, a = frag
        split = self.nfa.new_state()
        accept = self.nfa.new_state()
        self.nfa.add(split, EPSILON, s)
        self.nfa.add(split, EPSILON, accept)  # skip path
        self.nfa.add(a, EPSILON, accept)
        return (split, accept)

    # --- atoms --------------------------------------------------------------
    def _atom(self):
        c = self.peek()
        if c is None:
            raise ParseError(f"unexpected end of pattern {self.pat!r}")
        if c == "(":
            self.i += 1
            frag = self._alternation()
            self.expect(")")
            return frag
        if c == ")":
            raise ParseError(f"unbalanced parenthesis at position {self.i}")
        if c in "*+?":
            raise ParseError(
                f"nothing to repeat at position {self.i} in {self.pat!r}"
            )
        if c == "{":
            raise ParseError(f"bad repeat specifier at position {self.i}")
        if c == "|":
            raise ParseError(f"empty alternative at position {self.i}")
        self.i += 1
        start = self.nfa.new_state()
        accept = self.nfa.new_state()
        label = ANY if c == "." else c
        self.nfa.add(start, label, accept)
        return (start, accept)


# ---------------------------------------------------------------------------
# Compilation and simulation
# ---------------------------------------------------------------------------

def compile(pattern: str) -> NFA:
    """Compile *pattern* into a Thompson NFA (O(len(pattern)) states)."""
    return _Parser(pattern).parse()


def _epsilon_closure(nfa: NFA, states) -> frozenset:
    """All states reachable from *states* via epsilon edges only."""
    stack = list(states)
    seen = set(states)
    while stack:
        s = stack.pop()
        for label, dst in nfa.trans[s]:
            if label is EPSILON and dst not in seen:
                seen.add(dst)
                stack.append(dst)
    return frozenset(seen)


def fullmatch(pattern: str, string: str) -> bool:
    """Return True iff *pattern* matches ALL of *string*.

    Simulation strategy (Thompson/Pike style): maintain the set of states
    the NFA could occupy. For each input character, move every current
    state along character edges, then close under epsilon. Work per
    character is bounded by the NFA size, so total runtime is
    O(len(string) * len(pattern)) -- worst-case polynomial, never
    exponential. No backtracking, no memoization.
    """
    nfa = compile(pattern)
    current = _epsilon_closure(nfa, {nfa.start})
    for ch in string:
        nxt = set()
        for s in current:
            for label, dst in nfa.trans[s]:
                if label is ANY:
                    if ch != "\n":  # '.' does not match newline, like re
                        nxt.add(dst)
                elif label is not EPSILON and label == ch:
                    nxt.add(dst)
        if not nxt:
            return False  # dead -- prune immediately
        current = _epsilon_closure(nfa, nxt)
    return nfa.accept in current

